sn_aia_tool.script:
(function(inputs) {

    // only string inputs are allowed 
    // return outputs object where the keys in it are understandable by LLM  

    try {
        var gr = new GlideRecord("incident");
        gr.addQuery("number", inputs.incident_number);
        gr.query();

        if (!gr.next()) {
            return {
                status: "info",
                message: gs.getMessage("No incident found")
            };
        }

        gr.work_notes = inputs.work_note;
        gr.update();
        return gs.getMessage("Recommendations have been successfully updated.");
    } catch (e) {
        return {
            status: 'error',
            message: e.message
        };
    }


})(inputs);
